from abc import ABC, abstractmethod
from dataclasses import dataclass


# --- Domain ---

class PricingRule(ABC):
    @abstractmethod
    def applies_to(self, item_type: str) -> bool: ...

    @abstractmethod
    def adjust(self, value: float) -> float: ...


class TypeARule(PricingRule):
    def applies_to(self, item_type: str) -> bool:
        return item_type == 'A'

    def adjust(self, value: float) -> float:
        return value * 1.1


class TypeBRule(PricingRule):
    def applies_to(self, item_type: str) -> bool:
        return item_type == 'B'

    def adjust(self, value: float) -> float:
        return value * 0.9


class TypeCRule(PricingRule):
    def applies_to(self, item_type: str) -> bool:
        return item_type == 'C'

    def adjust(self, value: float) -> float:
        return value * 1.05


DEFAULT_RULES: list[PricingRule] = [TypeARule(), TypeBRule(), TypeCRule()]


# --- Application ---

@dataclass
class Item:
    type: str
    value: float


